        def f(x):
            return 1 if (x - n) < 1 << 31 else 0
        low, high = -10000, 10000
        while low < high:
            mid = (low + high) // 2
            if sum(f(x) for x in nums if x <= mid) >= k:
                high = mid
            else:
                low = mid + 1
        return low

    return count(0) if k == 1 else count(10000)

def solve(nums, k):
    def find_kth_smallest(nums, k):
            # Sort the list in ascending order
            sorted_nums = sorted(nums)
            # Return the k-th smallest element (1-based index)
            return sorted_nums[k - 1]

        return find_kth_smallest(nums, k)

def solve(n, edges):
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    for u, v in edges:
        union(u, v)

    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

