def solve(n, edges):
    # Union-Find (Disjoint Set Union) data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv

    # Process each edge
    for u, v in edges:
        union(u, v)

    # Count the number of distinct root parents
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

