def solve(n, edges):
    def dfs(node, visited):
        stack = [node]
        visited.add(node)
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
        return len(visited)

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            components += 1
            dfs(i, visited)

    return components

